#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Bilnov M3 v1 : localisations sur le commentaire central. Helper locations (teste), endpoint backfill CadAnnotation -> Comment (additif, idempotent), UI Voir-sur-le-plan + ajout de localisation + import DWG, ouverture auto ?file= sur la page projet. A appliquer apres 07."""
import base64, json, os, sys, subprocess
FILES={"src/lib/locations.ts": "", "src/lib/__tests__/locations.test.ts": "", "src/app/api/projects/[id]/comments/backfill-cad/route.ts": "", "src/app/projects/[id]/comments/page.tsx": ""}
EDITS=[["src/app/projects/[id]/page.tsx", "useRef-import", "dXNlRWZmZWN0LCB1c2VSZWYsIHVzZVN0YXRlLCB1c2VDYWxsYmFjaw==", "aW1wb3J0IFJlYWN0LCB7IHVzZUVmZmVjdCwgdXNlU3RhdGUsIHVzZUNhbGxiYWNrIH0gZnJvbSAncmVhY3QnOw==", "aW1wb3J0IFJlYWN0LCB7IHVzZUVmZmVjdCwgdXNlUmVmLCB1c2VTdGF0ZSwgdXNlQ2FsbGJhY2sgfSBmcm9tICdyZWFjdCc7"], ["src/app/projects/[id]/page.tsx", "open-file-query", "b3BlbmVkRnJvbVF1ZXJ5UmVm", "ICB1c2VFZmZlY3QoKCkgPT4geyB2b2lkIGxvYWRGaWxlcyhzZWxlY3RlZE5vZGVJZCk7IH0sIFtzZWxlY3RlZE5vZGVJZCwgbG9hZEZpbGVzXSk7", ""]]
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def write_files(root):
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True); c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
def patch(root):
    cache={}; ap=sk=0
    for f,name,dm,o,nw in EDITS:
        p=os.path.join(root,f)
        if not os.path.exists(p): print("!! introuvable:",f); sys.exit(1)
        src=cache.get(p) or open(p,encoding='utf-8').read(); marker,old,new=d(dm),d(o),d(nw)
        if marker in src: print("  = deja",name); cache[p]=src; sk+=1; continue
        if old not in src: print("!! ANCRE KO:",name,"@",f); sys.exit(2)
        src=src.replace(old,new,1); cache[p]=src; ap+=1; print("  ~ patche",name)
    for p,src in cache.items(): open(p,'w',encoding='utf-8').write(src)
    print("  ->",ap,"patche(s),",sk,"deja.")
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! echec (rc=%d)."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:])
    print("== Bilnov M3 v1 (localisations DWG + pont CAO) =="); write_files(root); patch(root)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Bilnov M3 v1 (localisations DWG + pont CAO) applique. Aucun git push.")
if __name__=='__main__': main()
